def solve(grid):
    a=np.array(grid); H,W=a.shape
    for c in range(10):
        sr=[i for i in range(H) if (a[i]==c).all()]
        sc=[j for j in range(W) if (a[:,j]==c).all()]
        if sr and sc:
            def groups(n,seps):
                g=[];cur=[]
                for i in range(n):
                    if i in seps:
                        if cur: g.append(cur); cur=[]
                    else: cur.append(i)
                if cur: g.append(cur)
                return g
            rg=groups(H,set(sr)); cg=groups(W,set(sc))
            res=[]
            for ri in rg:
                row=[]
                for ci in cg:
                    b=a[np.ix_(ri,ci)]
                    vals,cnt=np.unique(b,return_counts=True)
                    dom=int(vals[np.argmax(cnt)])
                    icnt=int((b!=dom).sum())
                    row.append(1 if icnt==2 else dom)
                res.append(row)
            return res
    return None
